// HasTurns applies the HasEdge predicate on the "turns" edge.
func HasTurns() predicate.KaguyaConversation {
	return predicate.KaguyaConversation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, TurnsTable, TurnsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTurnsWith applies the HasEdge predicate on the "turns" edge with a given conditions (other predicates).
func HasTurnsWith(preds ...predicate.KaguyaChatTurn) predicate.KaguyaConversation {
	return predicate.KaguyaConversation(func(s *sql.Selector) {
		step := newTurnsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KaguyaConversation) predicate.KaguyaConversation {
	return predicate.KaguyaConversation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KaguyaConversation) predicate.KaguyaConversation {
	return predicate.KaguyaConversation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KaguyaConversation) predicate.KaguyaConversation {
	return predicate.KaguyaConversation(sql.NotPredicates(p))
}
